import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Special Attacks and prepared actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/special-attacks.md","filePath":"en/guide/combat/special-attacks.md"}'),n={name:"en/guide/combat/special-attacks.md"};function s(o,a,d,l,c,p){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="special-attacks-and-prepared-actions" tabindex="-1">Special Attacks and prepared actions <a class="header-anchor" href="#special-attacks-and-prepared-actions" aria-label="Permalink to &quot;Special Attacks and prepared actions&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Experimental prepared repertoire · Not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Learn Special Attacks (SAs) through teachers, manuals, exploration and challenges.</li><li>Known techniques remain known; prepare a small repertoire for immediate use.</li><li>Familiarity improves execution modestly; timing and matchups still decide whether an action is useful.</li></ul><p><span id="at-a-glance"></span><span id="first-weapon-kits"></span><span id="trade-offs"></span><span id="preparation"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Meaning</th></tr></thead><tbody><tr><td>Preparation</td><td>A technique must be learned, prepared and compatible with your weapon; basic attacks do not take repertoire slots.</td></tr><tr><td>Offense</td><td>Queue a valid swing in Legacy; initiate an available action in Modern.</td></tr><tr><td>Defense</td><td>Brace and Riposte are manual responses with timing, stamina and matchup limits.</td></tr><tr><td>Changing your kit</td><td>Prepare outside active combat after a quiet interval; swapping cannot cancel recovery. INT is not a mandatory martial slot tax.</td></tr></tbody></table><p>Learning an SA does not guarantee a hit. Knowledge persists, while practical fluency can decline through disuse. Final repertoire capacity and future INT interactions remain unresolved.</p><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands</th></tr></thead><tbody><tr><td>UOR already included special attacks</td><td>Make techniques learned knowledge with a prepared repertoire and Familiarity.</td></tr><tr><td>Later UO assigns primary/secondary moves to weapons</td><td>Separate knowing a technique from preparing and executing it with compatible equipment.</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>You prepare Brace to answer a heavy committed attack. An opponent uses Feint instead: your defense spends time and stamina without receiving the blow you expected.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Modes</a> · <a href="/Syrolands-Public/en/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/actions.html">Read the full design specification</a></p>',16)])])}const m=e(n,[["render",s]]);export{u as __pageData,m as default};
